```java
// Approach 1: Extend Thread
class MyThread extends Thread {
    public void run() { System.out.println("Thread running"); }
}
new MyThread().start();

// Approach 2: Implement Runnable (preferred)
class MyTask implements Runnable {
    public void run() { System.out.println("Task running"); }
}
new Thread(new MyTask()).start();

// Lambda version (Java 8+)
new Thread(() -> System.out.println("Lambda thread")).start();
```

```java
Thread t = new Thread(() -> {
    System.out.println("In: " + Thread.currentThread().getName());
});

t.run();   // prints: In: main (same thread!)
t.start(); // prints: In: Thread-0 (new thread!)
```

```java
// Anonymous class (old way)
new Thread(new Runnable() {
    public void run() { System.out.println("old style"); }
}).start();

// Lambda (Java 8+)
new Thread(() -> System.out.println("lambda")).start();

// Method reference
new Thread(MyClass::doTask).start();

// Named lambda for reuse
Runnable task = () -> System.out.println("reusable");
new Thread(task).start();
```

```java
ExecutorService executor = Executors.newSingleThreadExecutor();

Callable<Integer> task = () -> {
    Thread.sleep(1000);
    return 42;
};

Future<Integer> future = executor.submit(task);
// Do other work...
Integer result = future.get(); // blocks until result available
System.out.println(result); // 42
executor.shutdown();
```

```java
// Fixed pool of 4 threads
ExecutorService pool = Executors.newFixedThreadPool(4);

// Submit multiple tasks
for (int i = 0; i < 10; i++) {
    final int taskId = i;
    pool.submit(() -> System.out.println("Task " + taskId));
}

pool.shutdown(); // stop accepting new tasks
pool.awaitTermination(30, TimeUnit.SECONDS);
```

```java
Thread monitor = new Thread(() -> {
    while (true) {
        checkHealth(); // background health check
        Thread.sleep(5000);
    }
});
monitor.setDaemon(true); // must be BEFORE start()
monitor.start();

// When main thread finishes, monitor is killed automatically
```
